def score_for(names, scores, target):
    low, high = 0, len(names) - 1
    while low <= high:
        mid = (low + high) // 2
        if names[mid] == target:
            return scores[mid]
        if names[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return "Not found"

